// TH14 synthetic training vocabulary; source etSprite type 12 -> target row 544 (radius 2.4).
// Source color 6 stays in the 0..15 valid range. Mapping per transcribe/th14/bullet-types.md.
const TH14_ARROWHEAD: int = 544;

// TH14 v1.00b st01bs::BossCard1, source lines 282-344; helpers BossCard1_at/at2 346-420.
// Source segment timer 0/2400 -> Boss2 is exit context only; this card runs an independent
// invincible segment: 120-frame opening buffer, 2400 source frames, then tail margin.
// Source t0 = pattern start; first shot at source t90 (card frame ~212).
const TIME_LIMIT: int = 2884;
const SOURCE_LIMIT: int = 2400;
const OPENING_BUFFER: int = 120;

xformdef CARD_ANGLE_ACCEL(r: fx, w: angle) {
    // Source per-bullet EX: ANIM(a=1), WAIT 60, ANGLE_ACCEL(a=60, r=F/60, s=RANDRAD/600).
    // Birth stage plus its animation wait omitted by user policy; accel starts at first
    // target effect update. stop_fx clears both POLAR_FX terms after the 60 updates.
    set_ang_vel(w);
    set_accel(r);
    wait(60);
    stop_fx();
}

sub card_at(a_count: int, g: fx, until: int) {
    // Source BossCard1_at: C = ANGLE_PLAYER - B*20 (B=0.17453292 rad = 10deg);
    // D starts at C + E*A, decreases by E; C increases by B each of 60 rounds.
    var e: angle = 1013bam; // source E = 0.097081 rad
    var ea: angle = 0bam;
    for i in 0..a_count { ea = ea + e; }
    var aim: angle = aim_player(); // source ANGLE_PLAYER snapshot at helper entry
    var c: angle = aim - 200deg;
    for round in 0..60 {
        var d: angle = c + ea;
        var f: fx = 0.8fx;
        for j in 0..a_count {
            if $frame >= until { return; }
            // Source samples RANDRAD once per bullet inside etExSet; -pi..pi scaled by 1/600.
            var w: angle = ((rand(65536)-32768)/600) as angle;
            var r: fx = f / 60fx;
            // etDist(20) along the bullet angle minus ANIM's 4*initial-speed retreat (4*0.4).
            var x: fx = $self_x + 18.4fx*cos(d);
            var y: fx = $self_y + 18.4fx*sin(d);
            _ = fire(TH14_ARROWHEAD, 6, x, y, 0.4fx, d, CARD_ANGLE_ACCEL(r, w), none);
            d = d - e;
            f = f + g;
        }
        c = c + 10deg;
        wait(2);
    }
}

sub card_at2(a_count: int, g: fx, until: int) {
    // Source BossCard1_at2: C = ANGLE_PLAYER + B*20; D starts at C - E*A, increases by E;
    // C decreases by B each round. Source E here is 0.388322 rad.
    var e: angle = 4050bam;
    var ea: angle = 0bam;
    for i in 0..a_count { ea = ea + e; }
    var aim: angle = aim_player();
    var c: angle = aim + 200deg;
    for round in 0..60 {
        var d: angle = c - ea;
        var f: fx = 0.8fx;
        for j in 0..a_count {
            if $frame >= until { return; }
            var w: angle = ((rand(65536)-32768)/600) as angle;
            var r: fx = f / 60fx;
            var x: fx = $self_x + 18.4fx*cos(d);
            var y: fx = $self_y + 18.4fx*sin(d);
            _ = fire(TH14_ARROWHEAD, 6, x, y, 0.4fx, d, CARD_ANGLE_ACCEL(r, w), none);
            d = d + e;
            f = f + g;
        }
        c = c - 10deg;
        wait(2);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    var until: int = $frame + SOURCE_LIMIT;
    // Source diffI(A,1,2,6,10), diffI(C,3,6,12,14), diffF(G,0.4,0.4,0.33,0.23).
    var rank: int = global(GVAR_RANK);
    var a_count: int = 1;
    var c_limit: int = 3;
    var g: fx = 0.4fx;
    if rank == 1 { a_count = 2; c_limit = 6; }
    if rank == 2 { a_count = 6; c_limit = 12; g = 0.33fx; }
    if rank == 3 { a_count = 10; c_limit = 14; g = 0.23fx; }
    // Source 294-296: clear old velocity, settle from the reachable (0,128) entry over 60 frames.
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(60); // source +60 time label
    loop {
        if $frame >= until { break; }
        wait(30); // 812
        card_at(a_count, g, until);
        if $frame >= until { break; }
        wait(120); // movePosTime has no wait; the next moveRand starts after this source wait
        card_move_rand();
        card_wait(60);
        if a_count < c_limit { a_count = a_count + 1; }
        if $frame >= until { break; }
        card_at2(a_count, g, until); // 1248
        if $frame >= until { break; }
        wait(120);
        card_move_rand();
        card_wait(60);
        if a_count < c_limit { a_count = a_count + 1; }
    }
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx); // Source setHitbox(48,48): native ordinary circle uses width*0.5.
    set_hurtbox(20fx); // Source setHurtbox(40,40); damage disabled by training invulnerability.
    spell_begin(0, 2, pattern, TIME_LIMIT, 500000, 0, 0);
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}

sub main() {
    // Entry HP 1500 from the Boss entry context; no DPS is simulated and hp never drops.
    _ = spawn_enemy(0fx, 128fx, 1500, 0, 0, 0, boss_main);
    loop { wait(600); }
}

// TH14 v1.00b BossCard1 movement only (source 412 moveRand + 504 moveLimit(0,128,240,64)).
// Shared int slot 0 = random-move step count; fx slots 0/1 = logical unit direction.
// The source attack does not read these slots; movement.ecl owns them.
// Limits: final position x in [-120,120], y in [96,160]; random-direction inner zone
// is the source quarter box x +-60, y 112..144 (width 240 / height 64).
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    // Source speed(k) = 2*(1 - k/60), k = 1..60; 412's mode arg does not drive the speed slot.
    var speed: fx = 0fx;
    if k < 60 { speed = ((60-k) as fx) * 2fx / 60fx; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // Source random direction: signed unit random * pi, then quarter/third scaling by position.
    // Values below are unwrapped BAM ints computed like the verified TH18 recipe.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -60fx {
        a = r/3;
    } else if $self_x > 60fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; } // source normalizes this branch before the fabs tests
    } else {
        a = r/4;
        var choose: int = rand(65536)%3; // source WORD modulo 3, including its tiny bias
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
        // Deliberately do not normalize this branch before the source fabs tests.
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +-pi/2 guard, epsilon 0.05 rad; nearest BAM boundaries (normal angle quantization).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    // Source moveRand ticks once per frame; arm the next source tick for the target phase-5 move.
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}
